"""Normalizacao dos slots antes de chamar a /quote. Higiene de ENTRADA, nao regra de negocio.

A API nao valida nada disto e responde 200 com preco errado (ver docs/FINDINGS.md 1.5): CEP ausente ou sem o zero a esquerda
nao aplica o agravo regional; `plano_id` vazio vira Essencial; `data_inicio` no passado e aceita. Por isso o agente normaliza e
valida ANTES de chamar. Na duvida, recusa o valor (o agente pergunta de novo) em vez de adivinhar.
"""
from __future__ import annotations

import re
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from datetime import date
from typing import Any


class SlotValueError(ValueError):
    """Valor de slot rejeitado. `code` e estavel e vai para logs e testes."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


@dataclass(frozen=True)
class SlotIssue:
    slot: str
    code: str


@dataclass(frozen=True)
class QuoteRequest:
    plano_id: str
    idade: int
    veiculo_ano: int
    cep: str | None = None            # 8 digitos; obrigatorio no fluxo de cotacao, opcional so na confirmacao da pre-checagem
    data_inicio: date | None = None   # hoje ou futura

    def to_payload(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"plano_id": self.plano_id, "idade": self.idade, "veiculo_ano": self.veiculo_ano}
        if self.cep is not None:
            payload["cep"] = self.cep
        if self.data_inicio is not None:
            payload["data_inicio"] = self.data_inicio.isoformat()
        return payload


_DIGITS = re.compile(r"[0-9]+")
_ISO_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _as_int(value: object, code: str) -> int:
    if isinstance(value, bool):
        raise SlotValueError(code)
    if isinstance(value, int):
        return value
    if isinstance(value, str) and _DIGITS.fullmatch(value.strip()):
        return int(value.strip())
    raise SlotValueError(code)


def normalize_cep(value: object) -> str:
    """CEP como texto de 8 digitos. 7 digitos (zero a esquerda perdido) NAO e completado: pergunta de novo."""
    if value is None or isinstance(value, bool):
        raise SlotValueError("cep_ausente")
    if isinstance(value, int):
        raise SlotValueError("cep_nao_texto")  # um inteiro ja perdeu o zero a esquerda
    if not isinstance(value, str):
        raise SlotValueError("cep_invalido")
    digits = re.sub(r"[.\-\s]", "", value)
    if not _DIGITS.fullmatch(digits):
        raise SlotValueError("cep_invalido")
    if len(digits) == 8:
        return digits
    raise SlotValueError("cep_incompleto" if len(digits) == 7 else "cep_invalido")


def normalize_plano(value: object, known_plans: Iterable[str]) -> str:
    if not isinstance(value, str) or not value.strip():
        raise SlotValueError("plano_ausente")
    plano = value.strip().lower()
    if plano not in set(known_plans):
        raise SlotValueError("plano_desconhecido")
    return plano


def normalize_ano(value: object, today: date) -> int:
    ano = _as_int(value, "ano_invalido")
    if ano < 1950 or ano > 2100:
        raise SlotValueError("ano_invalido")
    if ano > today.year:
        raise SlotValueError("ano_modelo_futuro")  # a API recusa como "fora das faixas"; quem decide e o humano
    return ano


def normalize_idade(value: object) -> int:
    idade = _as_int(value, "idade_invalida")
    if not 0 <= idade <= 200:
        raise SlotValueError("idade_invalida")
    return idade  # elegibilidade (18 a 75) e da API, nao daqui


def normalize_data_inicio(value: object, today: date) -> date:
    if isinstance(value, date):
        d = value
    elif isinstance(value, str) and _ISO_DATE.fullmatch(value.strip()):
        try:
            d = date.fromisoformat(value.strip())
        except ValueError:
            raise SlotValueError("data_invalida") from None
    else:
        raise SlotValueError("data_invalida")
    if d < today:
        raise SlotValueError("data_no_passado")
    return d


def build_quote_request(raw: Mapping[str, object], *, today: date, known_plans: Iterable[str]) -> QuoteRequest | tuple[SlotIssue, ...]:
    """Pedido de cotacao completo ou, se faltar ou for invalido algum slot, TODAS as pendencias de uma vez."""
    known = tuple(known_plans)
    normalizers = (
        ("plano_id", lambda v: normalize_plano(v, known)),
        ("idade", normalize_idade),
        ("veiculo_ano", lambda v: normalize_ano(v, today)),
        ("cep", normalize_cep),
        ("data_inicio", lambda v: normalize_data_inicio(v, today)),
    )
    values: dict[str, Any] = {}
    issues: list[SlotIssue] = []
    for slot, fn in normalizers:
        if raw.get(slot) in (None, ""):
            issues.append(SlotIssue(slot, "ausente"))
            continue
        try:
            values[slot] = fn(raw[slot])
        except SlotValueError as exc:
            issues.append(SlotIssue(slot, exc.code))
    return tuple(issues) if issues else QuoteRequest(**values)

"""Base de fatos injetada a partir do /planos: o UNICO material que o `reply` do LLM pode afirmar.

Cada fato tem um id, um texto e os TERMOS (cobertura, plano, carencia, franquia...) sobre os quais ele autoriza o LLM a falar.
O LLM declara em `facts_used` em quais fatos se apoiou; o guardrail confere que todo termo e todo numero do texto vem de fatos citados
(ou foi escrito pelo lead). A base e derivada do /planos, entao um plano novo ou uma carencia diferente entra sem mudar codigo.
Valores em dinheiro (franquia, mensalidade) NUNCA entram: vivem so nos templates de cotacao.
"""
from __future__ import annotations

import re
import unicodedata
from collections.abc import Mapping
from dataclasses import dataclass

COVERAGE_LABEL = {
    "colisao": "colisão", "roubo": "roubo", "furto": "furto", "terceiros": "danos a terceiros", "vidros": "vidros",
    "carro_reserva": "carro reserva", "assistencia_24h": "assistência 24h",
}
COVERAGE_IDS = frozenset(COVERAGE_LABEL)

# Termos que "carregam afirmacao". Aplicados ao texto SEM acentos e em minusculas.
_PLAIN_TERMS = {
    "colisao": r"\bcolis", "roubo": r"\broub", "furto": r"\bfurt", "terceiros": r"\bterceir", "vidros": r"\bvidro",
    "carro_reserva": r"carro[- ]reserva", "assistencia_24h": r"\bassistencia",
    "carencia": r"\bcarencia", "franquia": r"\bfranquia", "pro_rata": r"proporcional|pro[- ]?rata|primeiro pagamento",
}
_PLAIN = {k: re.compile(v) for k, v in _PLAIN_TERMS.items()}
_NUMBER_WORDS = {1: "um", 2: "dois", 3: "três", 4: "quatro", 5: "cinco"}


def strip_accents(text: str) -> str:
    return "".join(c for c in unicodedata.normalize("NFD", text) if unicodedata.category(c) != "Mn")


def _join(items: list[str]) -> str:
    return items[0] if len(items) == 1 else ", ".join(items[:-1]) + " e " + items[-1]


@dataclass(frozen=True)
class Fact:
    id: str
    text: str
    terms: frozenset[str]

    @property
    def numbers(self) -> frozenset[str]:
        return frozenset(re.findall(r"[0-9]+", self.text))


@dataclass(frozen=True)
class FactBase:
    facts: Mapping[str, Fact]
    plan_coverages: Mapping[str, frozenset[str]]   # "plan_<id>" -> coberturas do plano
    plan_patterns: Mapping[str, re.Pattern[str]]   # "plan_<id>" -> nome do plano (case-sensitive: "Completo" != "completo")

    @classmethod
    def from_planos(cls, planos: Mapping) -> FactBase:
        facts: dict[str, Fact] = {}
        coverages: dict[str, frozenset[str]] = {}
        patterns: dict[str, re.Pattern[str]] = {}
        plans = planos["planos"]
        for p in plans:
            term = f"plan_{p['id']}"
            cov = frozenset(p["coberturas"])
            coverages[term] = cov
            patterns[term] = re.compile(rf"\b{re.escape(p['nome'])}\b")
            labels = [COVERAGE_LABEL.get(c, c) for c in p["coberturas"]]
            facts[f"plano:{p['id']}"] = Fact(f"plano:{p['id']}", f"O plano {p['nome']} cobre {_join(labels)}.", frozenset({term}) | cov)
        n = len(plans)
        facts["planos"] = Fact("planos", f"A AutoSeguro tem {_NUMBER_WORDS.get(n, str(n))} planos: {_join([p['nome'] for p in plans])}.",
                               frozenset(coverages))
        car = planos["regras"]["carencia"]
        car_cov = [c for c in car["coberturas_com_carencia"]]
        facts["carencia"] = Fact(
            "carencia", f"{_join([COVERAGE_LABEL.get(c, c)[0].upper() + COVERAGE_LABEL.get(c, c)[1:] if i == 0 else COVERAGE_LABEL.get(c, c) for i, c in enumerate(car_cov)])} "
                        f"só passam a valer {car['dias']} dias depois do início da vigência (carência).",
            frozenset({"carencia"}) | frozenset(car_cov))
        if "entrada_meio_mes" in planos["regras"]:
            facts["pro_rata"] = Fact("pro_rata", "Quando a vigência começa no meio do mês, o primeiro pagamento é proporcional aos dias "
                                                 "restantes; os meses seguintes são integrais.", frozenset({"pro_rata"}))
        facts["franquia"] = Fact("franquia", "Cada plano tem uma franquia, a parte do prejuízo que fica com o segurado. "
                                             "O valor aparece na cotação.", frozenset({"franquia"}))
        return cls(facts, coverages, patterns)

    def ids(self) -> tuple[str, ...]:
        return tuple(self.facts)

    def render_for_prompt(self) -> str:
        return "\n".join(f"- [{f.id}] {f.text}" for f in self.facts.values())

    def find_terms(self, text: str) -> set[str]:
        """Termos que carregam afirmacao presentes em `text`."""
        plain = strip_accents(text).lower()
        found = {t for t, rx in _PLAIN.items() if rx.search(plain)}
        found |= {t for t, rx in self.plan_patterns.items() if rx.search(text)}
        return found

