ESCALATION_RATE = 0.10
THINKING_EXTRA_OUT = 250       # sensibilidade: raciocinio residual cobrado como saida


def call_usd(model: str, cache: bool, hit: float = 0.0, extra_out: int = 0, tok: dict | None = None) -> float:
    tok = tok or TOK
