"""Limite de taxa, cota diaria e backoff de 429 para provedores com free tier (OpenRouter: 20 req/min e 50 req/dia sem creditos).

Duas decisoes conservadoras, porque os docs do OpenRouter NAO dizem se requisicao que falha conta na cota:
  - TODA requisicao que saiu da maquina e contada (sucesso, 429, 5xx, timeout), no log `quota.jsonl`;
  - a cota e por dia UTC, e o log persiste entre execucoes: rodar o smoke duas vezes no mesmo dia soma.
429: se o provedor diz que o limite e DIARIO, para (nao adianta insistir); senao espera `max(Retry-After, backoff exponencial)` e tenta de novo,
ate `max_retries`. O espacamento entre chamadas tem 5% de folga sobre 60/rpm.
"""
from __future__ import annotations

import json
import time
from collections import deque
from collections.abc import Callable
from datetime import UTC, date, datetime
from pathlib import Path

from .base import LLMClient, LLMResult


class QuotaExhausted(RuntimeError):
    """A cota diaria acabou. Nenhuma requisicao foi feita."""


class RateLimiter:
    def __init__(self, rpm: int, *, clock: Callable[[], float] = time.monotonic, sleep: Callable[[float], None] = time.sleep,
                 safety: float = 1.05) -> None:
        self._rpm, self._clock, self._sleep = rpm, clock, sleep
        self._gap = 60.0 / rpm * safety
        self._window: deque[float] = deque()
        self._last: float | None = None

    def wait(self) -> None:
        now = self._clock()
        if self._last is not None and now < self._last + self._gap:
            self._sleep(self._last + self._gap - now)
            now = self._clock()
        while self._window and now - self._window[0] >= 60.0:
            self._window.popleft()
        if len(self._window) >= self._rpm:  # a janela deslizante de 60s nunca passa de `rpm` chamadas
            self._sleep(self._window[0] + 60.0 - now)
            now = self._clock()
            while self._window and now - self._window[0] >= 60.0:
                self._window.popleft()
        self._window.append(now)
        self._last = now


class QuotaLog:
    """Contador diario (UTC) persistido em JSONL. Nao guarda segredo, prompt nem resposta: so quando, provedor, modelo e desfecho."""

    def __init__(self, path: Path, daily_limit: int, *, now: Callable[[], datetime] = lambda: datetime.now(UTC)) -> None:
        self.path, self.daily_limit, self._now = path, daily_limit, now

    def _today_rows(self) -> list[dict]:
        if not self.path.exists():
            return []
        today, rows = self._now().date().isoformat(), []
        for line in self.path.read_text(encoding="utf-8").splitlines():
            try:
                row = json.loads(line)
            except ValueError:
                continue
            if isinstance(row, dict) and str(row.get("ts", ""))[:10] == today:
                rows.append(row)
        return rows

    def used_today(self) -> int:
        return sum(1 for r in self._today_rows() if r.get("kind") == "request")

    def exhausted_today(self) -> bool:
        return any(r.get("kind") == "daily_limit_hit" for r in self._today_rows())

    def remaining(self) -> int:
        return 0 if self.exhausted_today() else max(0, self.daily_limit - self.used_today())

    def utc_day(self) -> date:
        return self._now().date()

    def _append(self, row: dict) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open("a", encoding="utf-8") as fh:
            fh.write(json.dumps({"ts": self._now().isoformat(), **row}, ensure_ascii=False) + "\n")

    def record_request(self, provider: str, model: str, outcome: str, status: int | None) -> None:
        self._append({"kind": "request", "provider": provider, "model": model, "outcome": outcome, "status": status})

    def mark_exhausted(self, provider: str, model: str) -> None:
        self._append({"kind": "daily_limit_hit", "provider": provider, "model": model})


class ThrottledLLM:
    """Envolve um adaptador: respeita o rpm, conta cada requisicao, para na cota e trata o 429. O gate e o guardrail ficam POR FORA."""

    def __init__(self, inner: LLMClient, *, limiter: RateLimiter, quota: QuotaLog, max_retries: int = 3, backoff_base_s: float = 5.0,
                 backoff_cap_s: float = 60.0, sleep: Callable[[float], None] = time.sleep,
                 on_event: Callable[[str], None] | None = None) -> None:
        self._inner, self._limiter, self._quota = inner, limiter, quota
        self._max_retries, self._base, self._cap, self._sleep, self._on_event = max_retries, backoff_base_s, backoff_cap_s, sleep, on_event
        self.requests = 0
        self.retries = 0

    @property
    def provider(self) -> str:
        return self._inner.provider

    @property
    def model(self) -> str:
        return self._inner.model

    @property
    def system_prompt(self) -> str:
        return self._inner.system_prompt

    def __repr__(self) -> str:
        return f"ThrottledLLM({self._inner!r})"

    def turn(self, user_message: str) -> LLMResult:
        attempt = 0
        while True:
            if self._quota.remaining() <= 0:
                raise QuotaExhausted(f"cota diaria de {self._quota.daily_limit} requisicoes esgotada (dia UTC {self._quota.utc_day()})")
            self._limiter.wait()
            res = self._inner.turn(user_message)
            self.requests += 1
            self._quota.record_request(self.provider, self.model, res.error or "ok", res.http_status)
            if self._on_event:
                self._on_event(f"requisicao {self._quota.used_today()}/{self._quota.daily_limit} hoje ({res.error or 'ok'})")
            if res.http_status == 429:
                if res.quota_kind == "daily":
                    self._quota.mark_exhausted(self.provider, self.model)
                    return res
                if attempt < self._max_retries:
                    wait = min(self._cap, max(res.retry_after_s or 0.0, self._base * 2**attempt))
                    self.retries += 1
                    if self._on_event:
                        self._on_event(f"429: espera {wait:.1f}s e tenta de novo ({attempt + 1}/{self._max_retries})")
                    self._sleep(wait)
                    attempt += 1
                    continue
            return res

def __repr__(self) -> str:
    return f"OpenAICompatLLM(provider={self.provider!r}, model={self.model!r}, url={self._url!r})"  # sem a chave, de proposito

def request_body(self, user_message: str) -> dict[str, Any]:
    """O corpo EXATO enviado (testado). `reasoning` e `provider` sao extensoes do OpenRouter e so vao quando o destino e o OpenRouter."""
    body: dict[str, Any] = {
        "model": self.model, "max_tokens": self.max_tokens,
        "messages": [{"role": "system", "content": self.system_prompt}, {"role": "user", "content": user_message}]}
    if self.temperature is not None:
        body["temperature"] = self.temperature
    if self.structured_output == "json_schema":
        body["response_format"] = {"type": "json_schema", "json_schema": {"name": "turn_output", "strict": True, "schema": self._schema}}
    if self._openrouter:
        if self.reasoning_effort:
            body["reasoning"] = {"effort": self.reasoning_effort}
        if self.structured_output == "json_schema" or self.reasoning_effort:
            body["provider"] = {"require_parameters": True}  # so roteia a endpoints que suportam TODOS os parametros pedidos
    return body

def _post(self, body: bytes) -> tuple[int, dict[str, str], bytes]:
    headers = {"Content-Type": "application/json", "Accept": "application/json"}
    if self._api_key:
        headers["Authorization"] = f"Bearer {self._api_key}"
    req = urllib.request.Request(self._url, data=body, headers=headers, method="POST")
    box: dict[str, Any] = {}

    def run() -> None:
        try:
            with urllib.request.urlopen(req, timeout=self.timeout_s) as r:  # noqa: S310 - URL validada por assert_secure_url
                box["ok"] = (r.status, {k.lower(): v for k, v in r.headers.items()}, r.read())
        except urllib.error.HTTPError as exc:  # 4xx/5xx sao RESPOSTAS
            box["ok"] = (exc.code, {k.lower(): v for k, v in exc.headers.items()}, exc.read())
        except urllib.error.URLError as exc:
            box["err"] = "timeout" if isinstance(exc.reason, TimeoutError) else "connection"
        except TimeoutError:
            box["err"] = "timeout"
        except Exception:  # noqa: BLE001 - qualquer outra falha de rede/IO
            box["err"] = "connection"

    worker = threading.Thread(target=run, daemon=True)
    worker.start()
    worker.join(self.timeout_s)  # prazo TOTAL; o timeout do socket sozinho nao limita uma resposta que goteja
    if worker.is_alive() or box.get("err") == "timeout":
        raise _Timeout
    if "err" in box:
        raise _Connection
    return box["ok"]

def turn(self, user_message: str) -> LLMResult:
    t0 = time.perf_counter()
    try:
        status, headers, raw = self._post(json.dumps(self.request_body(user_message)).encode())
    except _Timeout:
        return LLMResult(None, "timeout", time.perf_counter() - t0, None, None)
    except _Connection:
        return LLMResult(None, "connection", time.perf_counter() - t0, None, None)
    return self._interpret(status, headers, raw, time.perf_counter() - t0)

def _interpret(self, status: int, headers: dict[str, str], raw: bytes, latency: float) -> LLMResult:
    try:
        body = json.loads(raw)
    except ValueError:
        body = None
    err = body.get("error") if isinstance(body, dict) else None
    message = err.get("message") if isinstance(err, dict) and isinstance(err.get("message"), str) else None
    detail = redact(message, [self._api_key], limit=200) or None
    code = err.get("code") if isinstance(err, dict) else None
    effective = status if status >= 400 else (code if isinstance(code, int) and code >= 400 else status)  # erro dentro de um HTTP 200

    if effective >= 400:
        quota_kind, retry_after = None, None
        if effective == 429:
            blob = (message or "") + json.dumps(err.get("metadata") or {}) if isinstance(err, dict) else ""
            quota_kind = "daily" if _DAILY.search(blob) else "rate"
            retry_after = _retry_after(headers)
        return LLMResult(None, f"http_{effective}", latency, None, None, http_status=effective, retry_after_s=retry_after,
                         quota_kind=quota_kind, detail=detail)
    if isinstance(err, dict):
        return LLMResult(None, f"provider_error:{code}", latency, None, None, http_status=status, detail=detail)
    choices = body.get("choices") if isinstance(body, dict) else None
    if not isinstance(choices, list) or not choices or not isinstance(choices[0], dict):
        return LLMResult(None, "no_choices", latency, None, None, http_status=status)
    choice = choices[0]
    usage, rid, served = _usage(body.get("usage")), body.get("id"), body.get("model")
    rid, served = rid if isinstance(rid, str) else None, served if isinstance(served, str) else None
    finish = choice.get("finish_reason")
    common = dict(latency_s=latency, usage=usage, request_id=rid, http_status=status, served_model=served)
    if finish == "length":  # tipicamente o raciocinio consumiu o max_tokens: conteudo vazio ou cortado
        return LLMResult(None, "max_tokens", stop_reason=finish, **common)
    if finish == "content_filter":
        return LLMResult(None, "content_filter", stop_reason=finish, **common)
    if finish == "error":
        return LLMResult(None, "provider_error:finish_reason", stop_reason=finish, detail=detail, **common)
    message_obj = choice.get("message") if isinstance(choice.get("message"), dict) else {}
    content = message_obj.get("content")
    if not isinstance(content, str) or not content.strip():
        return LLMResult(None, "no_text", stop_reason=finish, **common)
    return result_from_text(content, self._fact_ids, latency_s=latency, usage=usage, stop_reason=finish, request_id=rid,
                            http_status=status, served_model=served)

"""Servidor HTTP LOCAL que imita as APIs de LLM (OpenAI-compativel/OpenRouter e Anthropic). Sem rede, sem chave real."""
from __future__ import annotations

import json
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

# Chave de MENTIRA no formato do OpenRouter, montada em tempo de execucao: o literal completo nao pode existir na fonte (o scanner de segredos
# do repo reprovaria). Os testes de seguranca usam este valor como "canario": se ele aparecer em qualquer saida, o teste reprova.
CANARY_KEY = "sk-or" + "-v1-" + "CANARY0123456789abcdefABCDEF"

GOOD = {"slots": [{"slot": "idade", "value": "42", "uncertain": False}], "intent": "provide_info", "facts_used": [],
        "reply": "Anotado! Qual o seu CEP?"}


def chat_json(content: str | None, *, finish_reason: str = "stop", model: str = "vendor/model:free", prompt_tokens: int = 2400,
              completion_tokens: int = 130, reasoning_tokens: int = 0, cached_tokens: int = 0) -> dict:
    """Resposta no formato de chat completions do OpenRouter."""
    return {"id": "gen-test-123", "object": "chat.completion", "model": model,
            "choices": [{"index": 0, "finish_reason": finish_reason, "native_finish_reason": finish_reason,
                         "message": {"role": "assistant", "content": content}}],
            "usage": {"prompt_tokens": prompt_tokens, "completion_tokens": completion_tokens,
                      "prompt_tokens_details": {"cached_tokens": cached_tokens},
