        self.calls += 1
        self.payloads.append(payload)
        self.inflight += 1
        self.max_inflight = max(self.max_inflight, self.inflight)
        return _FakePending(self, step)


class _FakePending:
    def __init__(self, transport: FakeTransport, step: Step) -> None:
        self._t, self._step = transport, step
