"""Cliente da /quote, politica B (ver docs/PLAN.md, secoes 3 e 4 e docs/FINDINGS.md).

  - timeout de 10s por tentativa (a resposta lenta da API leva 8s e e VALIDA), no maximo 4 chamadas, orcamento de 15s ou o
    prazo restante do turno, o que for menor;
  - retry SO em falha transitoria: 5xx, 429, timeout, erro de conexao e corpo invalido. Nunca em 400 nem em 422;
  - backoff exponencial com jitter; nunca dorme alem do orcamento;
  - UMA chamada em voo por vez, por construcao: so abre a seguinte depois de concluir ou abandonar a anterior. Nao ha hedging;
  - classifica pelo CORPO, nao pelo status: o 422 de regra de negocio (`cotacao_recusada`) e o 422 do pydantic (`detail`) sao coisas
    diferentes;
  - um 200 so vira `Quote` se passar por validacao estrita (plano igual ao pedido, preco finito > 0, campos presentes, pro-rata
    presente quando a data de inicio nao e dia 1). A API devolve 200 errado em varios casos; o preco so chega ao lead se for coerente;
  - cada tentativa fica registrada (`Attempt`) para a tabela `quote_attempts`.

O tempo e o transporte sao injetados: os testes usam relogio virtual (sem `sleep`) e um transporte roteirizado.
"""
from __future__ import annotations

import json
import math
import random
import threading
import time
import urllib.error
import urllib.request
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any, Literal, Protocol

from . import budgets
from .slots import QuoteRequest

_EPS = 1e-9

ErrorKind = Literal["none", "refused", "invalid_schema", "invalid_payload", "http_5xx", "http_429", "timeout", "connection",
                    "bad_body", "plan_mismatch", "unexpected_status"]
Decision = Literal["accept", "stop_refused", "stop_invalid", "stop_unexpected", "retry", "stop_max_calls", "stop_budget"]


# --- transporte e relogio (injetaveis) --------------------------------------------------------------
@dataclass(frozen=True)
class RawResponse:
    status: int
    body: bytes


class TransportConnectionError(Exception):
    """Falha de rede ao completar a chamada."""


class Pending(Protocol):
    def wait(self, timeout_s: float) -> RawResponse | None:
        """Espera ate `timeout_s`. None = ainda nao terminou. Levanta TransportConnectionError em falha de rede."""
        ...

    def abandon(self) -> None:
        """O cliente desistiu desta chamada: o resultado nao interessa mais (deixa de contar como 'em voo')."""
        ...


class Transport(Protocol):
    def start(self, payload: dict[str, Any]) -> Pending: ...


class RealClock:
    def now(self) -> float:
        return time.monotonic()

    def sleep(self, seconds: float) -> None:
        time.sleep(seconds)


class _ThreadPending:
    def __init__(self, fn: Callable[[], RawResponse]) -> None:
        self._done = threading.Event()
        self._resp: RawResponse | None = None
        self._exc: Exception | None = None
        threading.Thread(target=self._run, args=(fn,), daemon=True).start()

    def _run(self, fn: Callable[[], RawResponse]) -> None:
        try:
            self._resp = fn()
        except TransportConnectionError as exc:
            self._exc = exc
        except Exception as exc:  # noqa: BLE001 - qualquer falha de rede/IO da thread vira erro de conexao
            self._exc = TransportConnectionError(type(exc).__name__)
        finally:
            self._done.set()

    def wait(self, timeout_s: float) -> RawResponse | None:
        if not self._done.wait(max(0.0, timeout_s)):
            return None
        if self._exc is not None:
            raise self._exc
        return self._resp

    def abandon(self) -> None:
        """A thread termina sozinha pelo timeout do socket; o resultado e descartado."""


class UrllibTransport:
    """HTTP real, so com a biblioteca padrao. Cada chamada roda numa thread para o cliente poder esperar com prazo."""

    def __init__(self, base_url: str, *, socket_timeout_s: float = budgets.QUOTE_ATTEMPT_TIMEOUT_S + 2.0) -> None:
        self._url = base_url.rstrip("/") + "/quote"
        self._timeout = socket_timeout_s

    def start(self, payload: dict[str, Any]) -> Pending:
        req = urllib.request.Request(self._url, data=json.dumps(payload).encode(), headers={"content-type": "application/json"},
                                     method="POST")

        def call() -> RawResponse:
            try:
                with urllib.request.urlopen(req, timeout=self._timeout) as r:  # noqa: S310 - URL vem de configuracao
                    return RawResponse(r.status, r.read())
            except urllib.error.HTTPError as exc:  # 4xx/5xx sao RESPOSTAS, nao falhas de rede
                return RawResponse(exc.code, exc.read())
            except (urllib.error.URLError, OSError) as exc:
                raise TransportConnectionError(type(exc).__name__) from exc

        return _ThreadPending(call)


# --- politica e resultados --------------------------------------------------------------------------
@dataclass(frozen=True)
class Policy:
    attempt_timeout_s: float = budgets.QUOTE_ATTEMPT_TIMEOUT_S
    max_calls: int = budgets.QUOTE_MAX_CALLS
    backoff_base_s: float = budgets.QUOTE_BACKOFF_BASE_S
    min_attempt_s: float = budgets.QUOTE_MIN_ATTEMPT_S


@dataclass(frozen=True)
class Attempt:
    n: int
    started_s: float          # desde o inicio da cotacao
    latency_s: float
    http_status: int | None   # None: timeout ou erro de conexao
    error_kind: ErrorKind
    decision: Decision

@dataclass(frozen=True, kw_only=True)
class _Outcome:
    attempts: tuple[Attempt, ...]
    elapsed_s: float
    hold_fired: bool = False
    hold_error: str | None = None


@dataclass(frozen=True, kw_only=True)
class Quote(_Outcome):
    plano_id: str
    plano_nome: str
    premio_mensal: float
    franquia: float
    coberturas: tuple[str, ...]
    multiplicadores: dict[str, float]
    carencia_dias: int
    carencia_coberturas: tuple[str, ...]
    primeiro_pagamento: float | None   # valor do primeiro pagamento pro-rata, quando existe
    pro_rata: dict[str, Any] | None
    raw: dict[str, Any]                # resposta da API como veio, para persistir em `quotes.response`


@dataclass(frozen=True, kw_only=True)
class Refused(_Outcome):
    """422 `cotacao_recusada`: decisao de negocio da API (idade, veiculo, plano). Nao e falha."""

    motivo: str


@dataclass(frozen=True, kw_only=True)
class InvalidInput(_Outcome):
    """Entrada recusada pela validacao (pydantic 422 ou 400): erro nosso, nao do lead e nem da API."""

    kind: Literal["schema", "payload"]
    detail: str


@dataclass(frozen=True, kw_only=True)
class Unavailable(_Outcome):
    """Sem cotacao dentro do orcamento. O componente que falhou e a API: vai junto do motivo no log e no pacote de handoff."""

    reason: Literal["attempts_exhausted", "budget_exhausted", "unexpected_response"]
    last_error: str
    component: str = "quote_api"


QuoteOutcome = Quote | Refused | InvalidInput | Unavailable


# --- classificacao (pura) ---------------------------------------------------------------------------
@dataclass(frozen=True)
class _Verdict:
    kind: Literal["ok", "refused", "invalid", "retry", "fatal"]
    error_kind: ErrorKind
    detail: str = ""
    sub: Literal["schema", "payload"] = "schema"
    data: dict[str, Any] | None = None


def _json(body: bytes) -> Any:
    try:
        return json.loads(body)
    except (ValueError, UnicodeDecodeError):
        return None


def _is_num(x: Any) -> bool:
    return isinstance(x, (int, float)) and not isinstance(x, bool) and math.isfinite(x)


def _quote_problem(b: Any, req: QuoteRequest) -> str | None:
    """None se o 200 e coerente; senao o nome do problema. Um 200 incoerente NUNCA vira preco."""
    if not isinstance(b, dict):
        return "not_object"
    if b.get("plano_id") != req.plano_id:
        return "plan_mismatch"
    if not isinstance(b.get("plano_nome"), str):
        return "plano_nome"
    if not _is_num(b.get("premio_mensal")) or b["premio_mensal"] <= 0:
        return "premio_mensal"
    if not _is_num(b.get("franquia")):
        return "franquia"
    if not (isinstance(b.get("coberturas"), list) and all(isinstance(c, str) for c in b["coberturas"])):
        return "coberturas"
    m = b.get("multiplicadores")
    if not (isinstance(m, dict) and all(_is_num(m.get(k)) for k in ("faixa_etaria", "idade_veiculo", "regiao"))):
        return "multiplicadores"
    c = b.get("carencia")
    if not (isinstance(c, dict) and isinstance(c.get("dias"), int) and not isinstance(c["dias"], bool)
            and isinstance(c.get("coberturas"), list)):
        return "carencia"
    if b.get("moeda") != "BRL":
        return "moeda"
    if req.data_inicio is not None and req.data_inicio.day != 1:  # a API so calcula pro-rata fora do dia 1; sem ele o preco nao e coerente
        pr = b.get("primeiro_pagamento_pro_rata")
        if not (isinstance(pr, dict) and all(_is_num(pr.get(k)) for k in ("valor_primeiro_pagamento", "dias_cobrados", "dias_no_mes"))):
            return "pro_rata"
    return None


def classify(resp: RawResponse, req: QuoteRequest) -> _Verdict:
    s, body = resp.status, _json(resp.body)
    if s == 200:
        problem = _quote_problem(body, req)
        if problem is None:
            return _Verdict("ok", "none", data=body)
        return _Verdict("retry", "plan_mismatch" if problem == "plan_mismatch" else "bad_body", problem)
    if s == 422:
        if isinstance(body, dict) and body.get("error") == "cotacao_recusada" and isinstance(body.get("motivo"), str):
            return _Verdict("refused", "refused", body["motivo"])
        if isinstance(body, dict) and isinstance(body.get("detail"), list):
            first = body["detail"][0] if body["detail"] else {}
            loc = ".".join(str(p) for p in first.get("loc", [])) if isinstance(first, dict) else ""
            msg = first.get("msg", "") if isinstance(first, dict) else ""
            return _Verdict("invalid", "invalid_schema", f"{loc}: {msg}", "schema")  # sem o `input`: nao repete dado do lead
        return _Verdict("retry", "bad_body", "422_inesperado")
    if s == 400:
        if isinstance(body, dict) and body.get("error") == "payload_invalido":
            return _Verdict("invalid", "invalid_payload", str(body.get("detalhe", "")), "payload")
        return _Verdict("fatal", "unexpected_status", "400_inesperado")
    if s == 429:
        return _Verdict("retry", "http_429")
    if s >= 500:
        return _Verdict("retry", "http_5xx")
    return _Verdict("fatal", "unexpected_status", f"status_{s}")


def _quote_fields(b: dict[str, Any]) -> dict[str, Any]:
    pr = b.get("primeiro_pagamento_pro_rata")
    return dict(
        plano_id=b["plano_id"], plano_nome=b["plano_nome"], premio_mensal=float(b["premio_mensal"]), franquia=float(b["franquia"]),
        coberturas=tuple(b["coberturas"]), multiplicadores={k: float(v) for k, v in b["multiplicadores"].items()},
        carencia_dias=b["carencia"]["dias"], carencia_coberturas=tuple(b["carencia"]["coberturas"]),
        primeiro_pagamento=float(pr["valor_primeiro_pagamento"]) if isinstance(pr, dict) else None,
        pro_rata=dict(pr) if isinstance(pr, dict) else None, raw=b)


class _Hold:
    """Dispara o callback de 'um instante' uma unica vez, no instante `at`, mesmo no meio de uma chamada bloqueada."""

    def __init__(self, at: float, callback: Callable[[], None]) -> None:
        self.at, self._callback = at, callback
        self.fired, self.error = False, None

    def fire_if_due(self, now: float) -> None:
        if not self.fired and now >= self.at - _EPS:
            self.fired = True
            try:
                self._callback()
            except Exception as exc:  # noqa: BLE001 - a mensagem de espera e best-effort; nunca pode perder a cotacao
                self.error = type(exc).__name__


# --- o cliente --------------------------------------------------------------------------------------
class QuoteClient:
    def __init__(self, transport: Transport, clock: Any = None, rng: random.Random | None = None, policy: Policy | None = None) -> None:
        self._transport = transport
        self._clock = clock or RealClock()
        self._rng = rng or random.Random()
        self._policy = policy or Policy()

    @classmethod
    def http(cls, base_url: str) -> QuoteClient:
        return cls(UrllibTransport(base_url))

    def quote(self, request: QuoteRequest, *, budget_s: float = budgets.QUOTE_BUDGET_S, hold_after_s: float | None = None,
              on_hold: Callable[[], None] | None = None) -> QuoteOutcome:
        """Devolve SEMPRE um resultado terminal, dentro de `budget_s`. `hold_after_s`: segundos desde AGORA em que `on_hold` deve
        disparar se ainda nao houver resultado (o orquestrador desconta o que o turno ja gastou)."""
        clock, pol = self._clock, self._policy
        t0 = clock.now()
        deadline = t0 + budget_s
        hold = _Hold(t0 + hold_after_s, on_hold) if hold_after_s is not None and on_hold is not None else None
        payload = request.to_payload()
        attempts: list[Attempt] = []
        last_error = "none"

        def done(cls: type, **fields: Any) -> Any:
            return cls(attempts=tuple(attempts), elapsed_s=clock.now() - t0, hold_fired=bool(hold and hold.fired),
                       hold_error=hold.error if hold else None, **fields)

        while True:
            if len(attempts) >= pol.max_calls:
                return done(Unavailable, reason="attempts_exhausted", last_error=last_error)
            remaining = deadline - clock.now()
            if remaining < pol.min_attempt_s:
                return done(Unavailable, reason="budget_exhausted", last_error=last_error)

            n, started = len(attempts) + 1, clock.now()
            if hold:
                hold.fire_if_due(started)
            pending = self._transport.start(payload)  # a anterior ja terminou ou foi abandonada: nunca ha duas em voo
            resp, transport_error = self._await(pending, started + min(pol.attempt_timeout_s, remaining), hold)
            latency = clock.now() - started
            verdict = _Verdict("retry", transport_error) if resp is None else classify(resp, request)  # type: ignore[arg-type]
            status = None if resp is None else resp.status

            def record(decision: Decision) -> None:
                attempts.append(Attempt(n, started - t0, latency, status, verdict.error_kind, decision))

            if verdict.kind == "ok":
                record("accept")
                return done(Quote, **_quote_fields(verdict.data or {}))
            if verdict.kind == "refused":
                record("stop_refused")
                return done(Refused, motivo=verdict.detail)
            if verdict.kind == "invalid":
                record("stop_invalid")
                return done(InvalidInput, kind=verdict.sub, detail=verdict.detail)
            if verdict.kind == "fatal":
                record("stop_unexpected")
                return done(Unavailable, reason="unexpected_response", last_error=verdict.error_kind)

            last_error = verdict.error_kind  # falha transitoria
            if n >= pol.max_calls:
                record("stop_max_calls")
                continue
            delay = pol.backoff_base_s * 2 ** (n - 1) * self._rng.uniform(0.5, 1.0)
            if clock.now() + delay + pol.min_attempt_s > deadline:
                record("stop_budget")
                return done(Unavailable, reason="budget_exhausted", last_error=last_error)
            record("retry")
            self._sleep(delay, hold)

    def _await(self, pending: Pending, end: float, hold: _Hold | None) -> tuple[RawResponse | None, str]:
        clock = self._clock
        while True:
            now = clock.now()
            wait_for = end - now
            if hold and not hold.fired:
                wait_for = min(wait_for, max(0.0, hold.at - now))
            try:
                resp = pending.wait(max(0.0, wait_for))
            except TransportConnectionError:
                return None, "connection"
            if resp is not None:
                return resp, ""
            now = clock.now()
            if hold:
                hold.fire_if_due(now)
            if now >= end - _EPS:
                pending.abandon()
                return None, "timeout"

    def _sleep(self, delay: float, hold: _Hold | None) -> None:
        clock = self._clock
        end = clock.now() + delay
        if hold and not hold.fired and hold.at < end:  # o instante de espera cai no meio do backoff: dorme ate la, avisa, segue
            clock.sleep(max(0.0, hold.at - clock.now()))
            hold.fire_if_due(clock.now())
        clock.sleep(max(0.0, end - clock.now()))

"""Orcamentos de tempo do turno: fonte unica para o cliente, o smoke, os simuladores e os testes.

CRITERIO de latencia (UM so, aprovado): p95 do TURNO <= 5s sem cotacao e <= 12s com cotacao.
Todo o resto abaixo e MECANISMO para cumprir o criterio ou rede de seguranca. Em particular, o limite por chamada de LLM
NAO e um numero solto: e DERIVADO do criterio (analysis/e2e_latency_sim.py: `derive_llm_call_limit`), e o smoke projeta o
p95 do turno a partir das latencias medidas (`project_turn_p95`).
"""
from __future__ import annotations

# --- criterio (aprovado) -----------------------------------------------------------------------------
TURN_P95_NO_QUOTE_S = 5.0
TURN_P95_WITH_QUOTE_S = 12.0

# --- mecanismos --------------------------------------------------------------------------------------
HOLD_AFTER_S = 2.5          # "um instante", contado desde a CHEGADA da mensagem: garante silencio <= 3s
TURN_CEILING_S = 20.0       # rede de seguranca: estourou => mensagem honesta + handoff, nunca silencio
OVERHEAD_S = 0.10           # webhook/terminal + SQLite + mascaramento + render de template

LLM_CALL_TIMEOUT_S = 6.0    # por tentativa
LLM_MAX_ATTEMPTS = 2        # 1 retry

# --- politica B da /quote ----------------------------------------------------------------------------
QUOTE_BUDGET_S = 15.0
QUOTE_ATTEMPT_TIMEOUT_S = 10.0
QUOTE_MAX_CALLS = 4
QUOTE_BACKOFF_BASE_S = 0.3
QUOTE_MIN_ATTEMPT_S = 1.0   # com menos orcamento que isso, nem tenta

# --- reply do LLM ------------------------------------------------------------------------------------
REPLY_TARGET_WORDS = 40     # pedido no prompt (tom de WhatsApp)
REPLY_HARD_MAX_WORDS = 50   # o guardrail reprova acima disso
"""Fast-path ESTRITO por regex: CANDIDATO, DESLIGADO por padrao. Nada no produto o chama.

Existe para ser MEDIDO pelo smoke-llm (divergencia regex vs LLM nas mesmas mensagens). Se divergir, sai; se nao divergir, so entra se o
ganho medido justificar (docs/PLAN.md, secoes 3 e 5.1). O risco que ele carrega e extrair o slot errado em silencio e chegar a um preco errado,
por isso so vale quando o turno e RESPOSTA DIRETA ao slot que foi perguntado e o valor e INEQUIVOCO: a mensagem inteira tem que casar. Qualquer
texto a mais, qualquer duvida, qualquer formato fora disto devolve None e a mensagem vai para o LLM.
"""
from __future__ import annotations

import re
from datetime import date

_ANO = re.compile(r"(?:(?:o\s+)?ano\s*(?:é|e|:)?\s*)?((?:19|20)[0-9]{2})", re.IGNORECASE)
_IDADE = re.compile(r"(?:tenho\s+)?([0-9]{2,3})(?:\s*anos)?", re.IGNORECASE)
_CEP = re.compile(r"(?:(?:o\s+|meu\s+)?cep\s*(?:é|e|:)?\s*)?([0-9]{5})[-.\s]?([0-9]{3})", re.IGNORECASE)


def fast_extract(asked_slot: str | None, text: str, *, today: date) -> str | None:
    """Valor normalizado do slot perguntado, ou None. Idade e ano: so numero plausivel; CEP: 8 digitos."""
    if asked_slot is None:
        return None
    t = text.strip()
    if asked_slot == "veiculo_ano" and (m := _ANO.fullmatch(t)) and 1950 <= int(m.group(1)) <= today.year:
        return m.group(1)
    if asked_slot == "idade" and (m := _IDADE.fullmatch(t)) and 18 <= int(m.group(1)) <= 110:
        return m.group(1)
    if asked_slot == "cep" and (m := _CEP.fullmatch(t)):
        return m.group(1) + m.group(2)
    return None
"""Saida estruturada de UMA chamada por mensagem: {slots, intent, facts_used, reply}.

Decisoes de desenho (ver docs/PLAN.md, secao 5):
  - `slots` e uma LISTA que so contem o que o lead disse nesta mensagem. A API de saida estruturada exige todos os campos em `required`
    e nao tem campo opcional, entao um objeto com 5 slots obrigatorios gastaria tokens com `null`. A lista e compacta por construcao.
  - `facts_used` e um enum com os ids reais da base de fatos: o modelo nao consegue citar um fato que nao existe.
  - O esquema usa so o subconjunto aceito: objetos com additionalProperties=false, enum, array, string, boolean. Sem limites de tamanho:
    o teto de ~40 palavras do `reply` vive no prompt e no guardrail, nao aqui.
"""
from __future__ import annotations

import re
from collections.abc import Mapping, Sequence
from dataclasses import dataclass
from typing import Any

SLOT_NAMES = ("idade", "veiculo_ano", "cep", "necessidade", "data_inicio")
NECESSIDADES = ("basica", "terceiros_vidros", "completa")
INTENTS = ("greeting", "provide_info", "correction", "ask_coverage_question", "question_not_in_facts", "price_objection",
           "wants_human", "complaint", "claim", "cancel", "ready_to_close", "out_of_scope", "unclear")


def response_schema(fact_ids: Sequence[str]) -> dict[str, Any]:
    return {
        "type": "object",
        "properties": {
            "slots": {"type": "array", "items": {
                "type": "object",
                "properties": {"slot": {"type": "string", "enum": list(SLOT_NAMES)}, "value": {"type": "string"},
                               "uncertain": {"type": "boolean"}},
                "required": ["slot", "value", "uncertain"], "additionalProperties": False}},
            "intent": {"type": "string", "enum": list(INTENTS)},
            "facts_used": {"type": "array", "items": {"type": "string", "enum": list(fact_ids)}},
            "reply": {"type": "string"},
        },
        "required": ["slots", "intent", "facts_used", "reply"],
        "additionalProperties": False,
    }


class OutputError(ValueError):
    """Saida do modelo fora do contrato (nao deveria ocorrer com saida estruturada; validamos mesmo assim)."""


@dataclass(frozen=True)
class SlotValue:
    slot: str
    value: str
    uncertain: bool


@dataclass(frozen=True)
class TurnOutput:
    slots: tuple[SlotValue, ...]
    intent: str
    facts_used: tuple[str, ...]
    reply: str

    def entries(self, slot: str) -> list[SlotValue]:
        return [s for s in self.slots if s.slot == slot]

    def ambiguous(self) -> frozenset[str]:
        """Slots marcados como incertos pelo modelo OU informados duas vezes com valores diferentes."""
        out = {s.slot for s in self.slots if s.uncertain}
        for slot in {s.slot for s in self.slots}:
            if len({re.sub(r"\D", "", s.value) or s.value.strip().lower() for s in self.entries(slot)}) > 1:
                out.add(slot)
        return frozenset(out)

    def value(self, slot: str) -> str | None:
        """O valor do slot SO quando e inequivoco: uma unica leitura e nao marcada como incerta. Senao None (o agente pergunta)."""
        e = self.entries(slot)
        if len(e) == 1 and not e[0].uncertain:
            return e[0].value
        return None


def parse_turn_output(obj: object, fact_ids: Sequence[str]) -> TurnOutput:
    if not isinstance(obj, Mapping) or set(obj) != {"slots", "intent", "facts_used", "reply"}:
        raise OutputError("chaves inesperadas")
    if not isinstance(obj["slots"], list):
        raise OutputError("slots nao e lista")
    slots = []
    for s in obj["slots"]:
        if not isinstance(s, Mapping) or set(s) != {"slot", "value", "uncertain"}:
            raise OutputError("slot mal formado")
        if s["slot"] not in SLOT_NAMES or not isinstance(s["value"], str) or not isinstance(s["uncertain"], bool):
            raise OutputError("slot invalido")
        slots.append(SlotValue(s["slot"], s["value"], s["uncertain"]))
    if obj["intent"] not in INTENTS:
        raise OutputError("intent invalido")
    fu = obj["facts_used"]
    if not isinstance(fu, list) or not all(isinstance(f, str) for f in fu):
        raise OutputError("facts_used invalido")
    if not isinstance(obj["reply"], str):
        raise OutputError("reply invalido")
    return TurnOutput(tuple(slots), obj["intent"], tuple(fu), obj["reply"])  # ids de fato desconhecidos: quem reprova e o guardrail
"""Tipos comuns da camada de LLM, que NAO dependem de provedor.

Contrato: um adaptador (Anthropic, OpenRouter, qualquer endpoint compativel com OpenAI) so sabe falar com o seu provedor e devolver texto.
Tudo que importa para a seguranca fica ACIMA dele:
  - a validacao LOCAL do formato (`result_from_text`): nao se confia em "saida estruturada garantida" de provedor nenhum;
  - o gate de PII e o guardrail do `reply` (`llm/guarded.py`), aplicados a qualquer adaptador pela fabrica (`llm/factory.py`).
"""
from __future__ import annotations

import json
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol

from .schema import OutputError, TurnOutput, parse_turn_output


@dataclass(frozen=True)
class Usage:
    input_tokens: int
    output_tokens: int
    cache_read_tokens: int = 0
    cache_write_tokens: int = 0
    reasoning_tokens: int = 0   # ja incluidos em output_tokens quando o provedor informa


@dataclass(frozen=True)
class LLMResult:
    output: TurnOutput | None
    # "timeout" | "connection" | "http_<status>" | "refusal" | "max_tokens" | "content_filter" | "no_text" | "no_choices"
    # | "provider_error:<code>" | "invalid_output:<motivo>"
    error: str | None
    latency_s: float
    usage: Usage | None
    stop_reason: str | None
    request_id: str | None = None
    http_status: int | None = None
    retry_after_s: float | None = None   # dica do provedor num 429
    quota_kind: str | None = None        # num 429: "daily" (esgotou o dia) | "rate" (limite por minuto ou do provedor)
    detail: str | None = None            # explicacao curta do provedor, JA sem segredos
    served_model: str | None = None      # o modelo que de fato respondeu (o roteador pode trocar)


class LLMClient(Protocol):
    provider: str
    model: str
    system_prompt: str

    def turn(self, user_message: str) -> LLMResult: ...


def outcome_class(error: str | None) -> str:
    """Quem falhou. "answered": o provedor entregou uma resposta (boa ou ruim: saida fora do schema, truncada ou vazia e falha do MODELO). "blocked": o provedor
    bloqueou (`content_filter`), que nao e erro de formato do modelo. "service": timeout, conexao, 429, 5xx e erro de protocolo: falha do servico, nao da conversa."""
    if error is None or error.startswith("invalid_output") or error in ("max_tokens", "no_text", "no_choices"):
        return "answered"
    return "blocked" if error == "content_filter" else "service"


def result_from_text(text: str, fact_ids: Sequence[str], *, latency_s: float, usage: Usage | None, stop_reason: str | None,
                     request_id: str | None = None, http_status: int | None = None, served_model: str | None = None) -> LLMResult:
    """Validacao LOCAL e unica, igual para todo provedor. Saida que nao casa com o esquema NUNCA vira dado: vira erro, e o orquestrador
    cai no template ou escala. Sem 'conserto': JSON dentro de cerca de markdown, por exemplo, e invalido."""
    common = dict(latency_s=latency_s, usage=usage, stop_reason=stop_reason, request_id=request_id, http_status=http_status,
                  served_model=served_model)
    try:
        obj = json.loads(text)
    except ValueError as exc:
        return LLMResult(None, f"invalid_output:{type(exc).__name__}", **common)
    try:
        return LLMResult(parse_turn_output(obj, fact_ids), None, **common)
    except OutputError as exc:
        return LLMResult(None, f"invalid_output:{type(exc).__name__}", **common)
"""Fabrica da camada de LLM: a UNICA porta de entrada do produto para um cliente de LLM.

Devolve sempre um `GuardedLLM` (gate de PII + guardrail por fora de qualquer adaptador). Trocar `LLM_PROVIDER` troca o adaptador e nao
contorna nenhuma protecao. Os adaptadores continuam importaveis (os testes os exercitam), mas o produto so os obtem por aqui.
"""
from __future__ import annotations

from collections.abc import Callable
from typing import Any
from urllib.parse import urlparse

from ..facts import FactBase
from .base import LLMClient
from .claude import ClaudeLLM
from .config import ConfigError, LLMConfig
from .guarded import GuardedLLM
from .openai_compat import OpenAICompatLLM

_LOCAL_HOSTS = ("localhost", "127.0.0.1", "::1")


def make_adapter(cfg: LLMConfig, fact_base: FactBase, *, client: Any = None) -> LLMClient:
    if cfg.provider == "anthropic":
        return ClaudeLLM(cfg.model, fact_base, client=client, api_key=cfg.api_key, max_tokens=cfg.max_tokens, timeout_s=cfg.timeout_s,
                         base_url=cfg.base_url)
    local = (urlparse(cfg.base_url or "").hostname or "") in _LOCAL_HOSTS
    if not cfg.api_key and not local:
        raise ConfigError(cfg.missing_key_message())
    return OpenAICompatLLM(cfg.model, fact_base, base_url=cfg.base_url or "", api_key=cfg.api_key, provider=cfg.provider,
                           structured_output=cfg.structured_output, reasoning_effort=cfg.reasoning_effort, max_tokens=cfg.max_tokens,
                           timeout_s=cfg.timeout_s, temperature=cfg.temperature)


def make_llm(cfg: LLMConfig, fact_base: FactBase, *, wrap: Callable[[LLMClient], LLMClient] | None = None, client: Any = None) -> GuardedLLM:
    """`wrap`: decorador opcional ENTRE o adaptador e o guarda (ex.: `ThrottledLLM` para o free tier). O guarda e sempre o mais externo."""
    adapter = make_adapter(cfg, fact_base, client=client)
    return GuardedLLM(wrap(adapter) if wrap else adapter, fact_base)
"""Normalizacao dos slots antes de chamar a /quote. Higiene de ENTRADA, nao regra de negocio.

A API nao valida nada disto e responde 200 com preco errado (ver docs/FINDINGS.md 1.5): CEP ausente ou sem o zero a esquerda
nao aplica o agravo regional; `plano_id` vazio vira Essencial; `data_inicio` no passado e aceita. Por isso o agente normaliza e
valida ANTES de chamar. Na duvida, recusa o valor (o agente pergunta de novo) em vez de adivinhar.
"""
from __future__ import annotations

import re
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from datetime import date
from typing import Any


class SlotValueError(ValueError):
    """Valor de slot rejeitado. `code` e estavel e vai para logs e testes."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


@dataclass(frozen=True)
class SlotIssue:
    slot: str
    code: str


@dataclass(frozen=True)
class QuoteRequest:
    plano_id: str
    idade: int
    veiculo_ano: int
    cep: str | None = None            # 8 digitos; obrigatorio no fluxo de cotacao, opcional so na confirmacao da pre-checagem
    data_inicio: date | None = None   # hoje ou futura

    def to_payload(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"plano_id": self.plano_id, "idade": self.idade, "veiculo_ano": self.veiculo_ano}
        if self.cep is not None:
            payload["cep"] = self.cep
        if self.data_inicio is not None:
            payload["data_inicio"] = self.data_inicio.isoformat()
        return payload


_DIGITS = re.compile(r"[0-9]+")
_ISO_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _as_int(value: object, code: str) -> int:
    if isinstance(value, bool):
        raise SlotValueError(code)
    if isinstance(value, int):
        return value
    if isinstance(value, str) and _DIGITS.fullmatch(value.strip()):
        return int(value.strip())
    raise SlotValueError(code)


def normalize_cep(value: object) -> str:
    """CEP como texto de 8 digitos. 7 digitos (zero a esquerda perdido) NAO e completado: pergunta de novo."""
    if value is None or isinstance(value, bool):
        raise SlotValueError("cep_ausente")
    if isinstance(value, int):
        raise SlotValueError("cep_nao_texto")  # um inteiro ja perdeu o zero a esquerda
    if not isinstance(value, str):
        raise SlotValueError("cep_invalido")
    digits = re.sub(r"[.\-\s]", "", value)
    if not _DIGITS.fullmatch(digits):
        raise SlotValueError("cep_invalido")
    if len(digits) == 8:
        return digits
    raise SlotValueError("cep_incompleto" if len(digits) == 7 else "cep_invalido")


def normalize_plano(value: object, known_plans: Iterable[str]) -> str:
    if not isinstance(value, str) or not value.strip():
        raise SlotValueError("plano_ausente")
    plano = value.strip().lower()
    if plano not in set(known_plans):
        raise SlotValueError("plano_desconhecido")
    return plano


def normalize_ano(value: object, today: date) -> int:
    ano = _as_int(value, "ano_invalido")
    if ano < 1950 or ano > 2100:
        raise SlotValueError("ano_invalido")
    if ano > today.year:
        raise SlotValueError("ano_modelo_futuro")  # a API recusa como "fora das faixas"; quem decide e o humano
    return ano


def normalize_idade(value: object) -> int:
    idade = _as_int(value, "idade_invalida")
    if not 0 <= idade <= 200:
        raise SlotValueError("idade_invalida")
    return idade  # elegibilidade (18 a 75) e da API, nao daqui


def normalize_data_inicio(value: object, today: date) -> date:
    if isinstance(value, date):
        d = value
    elif isinstance(value, str) and _ISO_DATE.fullmatch(value.strip()):
        try:
            d = date.fromisoformat(value.strip())
        except ValueError:
            raise SlotValueError("data_invalida") from None
    else:
        raise SlotValueError("data_invalida")
    if d < today:
        raise SlotValueError("data_no_passado")
    return d


def build_quote_request(raw: Mapping[str, object], *, today: date, known_plans: Iterable[str]) -> QuoteRequest | tuple[SlotIssue, ...]:
    """Pedido de cotacao completo ou, se faltar ou for invalido algum slot, TODAS as pendencias de uma vez."""
    known = tuple(known_plans)
    normalizers = (
        ("plano_id", lambda v: normalize_plano(v, known)),
        ("idade", normalize_idade),
        ("veiculo_ano", lambda v: normalize_ano(v, today)),
        ("cep", normalize_cep),
        ("data_inicio", lambda v: normalize_data_inicio(v, today)),
    )
    values: dict[str, Any] = {}
    issues: list[SlotIssue] = []
    for slot, fn in normalizers:
        if raw.get(slot) in (None, ""):
            issues.append(SlotIssue(slot, "ausente"))
            continue
        try:
            values[slot] = fn(raw[slot])
        except SlotValueError as exc:
            issues.append(SlotIssue(slot, exc.code))
    return tuple(issues) if issues else QuoteRequest(**values)

