"""Destino do handoff: o agente entrega um `HandoffPackage` a um `HandoffSink` e nao sabe o que ha do outro lado.

Padrao (Etapa 2b): `SqliteSink`. Para plugar CRM ou fila, implemente `HandoffSink` e passe a suite de
`tests/sink_contract.py`; o agente nao muda. Aqui vive SO a interface: nenhuma integracao esta implementada.

Contrato de um sink (cada item e verificado por `tests/sink_contract.py`):
  1. Idempotente por `package.trace_id`: entregar de novo devolve o mesmo recibo e nao duplica nada.
  2. Nao altera o pacote.
  3. Falha transitoria -> `SinkUnavailable` (o chamador mantem o handoff pendente e tenta de novo).
     Falha permanente (o destino recusa o pacote) -> `SinkRejected` (repetir nao adianta; alertar).
     Nunca perde o pacote em silencio e nao lanca outra excecao para esses dois casos.
  4. Sincrono. Cada sink aplica o proprio timeout; o orquestrador nao deixa o lead esperando por ele (ordem abaixo).
  5. Nao grava nem loga nada alem dos campos do pacote, que e livre de identificadores diretos por construcao.

Ordem no orquestrador (2b): 1) grava o pacote no SQLite, que e o registro de rastreabilidade e sempre existe;
2) responde ao lead; 3) entrega ao sink configurado. Se o sink falhar, o handoff fica `pending` para nova tentativa e o
que foi dito ao lead continua verdadeiro, porque o registro local ja existe. Um CRM entra ALEM do SQLite, nunca no lugar.
"""
from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from datetime import datetime
from enum import StrEnum
from types import MappingProxyType
from typing import Literal, Protocol, runtime_checkable

SCHEMA_VERSION = 1
MAX_RECENT_MESSAGES = 10
# Unicos campos de qualificacao permitidos no pacote. Um campo novo (ex.: "cpf", "nome") e rejeitado de proposito.
QUALIFICATION_SLOTS = ("idade", "veiculo_ano", "cep", "plano_id", "data_inicio")


class HandoffReason(StrEnum):
    """Motivo fixo do handoff. Vocabulario versionado: mudar um valor quebra quem consome o pacote."""

    QUOTE_UNAVAILABLE = "QUOTE_UNAVAILABLE"
    HUMAN_REQUESTED = "HUMAN_REQUESTED"
    COMPLAINT = "COMPLAINT"
    CLAIM_SINISTRO = "CLAIM_SINISTRO"
    CANCELLATION = "CANCELLATION"
    DATA_AMBIGUOUS = "DATA_AMBIGUOUS"
    MEDIA_UNREADABLE = "MEDIA_UNREADABLE"
    READY_TO_CLOSE = "READY_TO_CLOSE"
    CONVERSATION_STALLED = "CONVERSATION_STALLED"
    PRICE_OBJECTION = "PRICE_OBJECTION"
    OUT_OF_SCOPE = "OUT_OF_SCOPE"
    SAFETY_GUARD = "SAFETY_GUARD"


class FailedComponent(StrEnum):
    """Componente que falhou. O MOTIVO e a causa raiz e decide o codigo; o componente diz ONDE olhar. As duas coisas sao logadas."""

    LLM = "llm"
    GUARDRAIL = "guardrail"
    QUOTE_API = "quote_api"
    QUOTE_CLIENT = "quote_client"
    PRECHECK = "precheck"
    MASKER = "masker"
    STORE = "store"
    SINK = "sink"
    ORCHESTRATOR = "orchestrator"   # excecao inesperada no proprio orquestrador: o lead nunca fica sem resposta


# Estes motivos descrevem uma FALHA, entao exigem dizer qual componente falhou. Os demais sao decisoes (pedido do lead etc).
REASONS_REQUIRING_COMPONENT = frozenset({HandoffReason.QUOTE_UNAVAILABLE, HandoffReason.SAFETY_GUARD})


@dataclass(frozen=True)
class QuoteRef:
    """Referencia a ultima cotacao da conversa (o valor so existe quando a API respondeu 200)."""

    quote_id: str
    plano_id: str
    status: Literal["ok", "refused", "invalid", "unavailable"]
    premio_mensal: float | None = None


@dataclass(frozen=True)
class MaskedMessage:
    """Mensagem ja mascarada. O mascaramento e feito antes de chegar aqui; o pacote nunca carrega texto cru."""

    role: Literal["lead", "agent"]
    text: str
    ts: datetime


@dataclass(frozen=True)
class HandoffPackage:
    trace_id: str
    reason: HandoffReason
    created_at: datetime  # com fuso (UTC)
    qualification: Mapping[str, str | int | None]
    missing: tuple[str, ...]
    last_quote: QuoteRef | None
    recent_messages: tuple[MaskedMessage, ...]
    told_to_lead: str  # o texto EXATO enviado ao lead: o humano precisa saber o que foi prometido
    precheck: Literal["ok", "recusa_provavel"] | None = None
    failed_component: FailedComponent | None = None
    schema_version: int = SCHEMA_VERSION

    def __post_init__(self) -> None:
        if self.reason in REASONS_REQUIRING_COMPONENT and self.failed_component is None:
            raise ValueError(f"{self.reason.value} exige failed_component: o motivo diz o que houve, o componente diz onde")
        if self.created_at.tzinfo is None:
            raise ValueError("created_at precisa ter fuso horario (UTC)")
        if not self.told_to_lead.strip():
            raise ValueError("told_to_lead vazio: o pacote nao pode existir sem o que foi dito ao lead")
        extra = set(self.qualification) - set(QUALIFICATION_SLOTS)
        if extra:
            raise ValueError(f"campos de qualificacao nao permitidos: {sorted(extra)}")
        if len(self.recent_messages) > MAX_RECENT_MESSAGES:
            raise ValueError(f"no maximo {MAX_RECENT_MESSAGES} mensagens recentes")
        object.__setattr__(self, "qualification", MappingProxyType(dict(self.qualification)))  # somente leitura

    def to_dict(self) -> dict[str, object]:
        """Forma serializavel (JSON) entregue aos sinks. Estavel por `schema_version`."""
        q = self.last_quote
        return {
            "schema_version": self.schema_version,
            "trace_id": self.trace_id,
            "reason": self.reason.value,
            "created_at": self.created_at.isoformat(),
            "qualification": dict(self.qualification),
            "missing": list(self.missing),
            "last_quote": None if q is None else {"quote_id": q.quote_id, "plano_id": q.plano_id,
                                                   "status": q.status, "premio_mensal": q.premio_mensal},
            "precheck": self.precheck,
            "failed_component": None if self.failed_component is None else self.failed_component.value,
            "recent_messages": [{"role": m.role, "text": m.text, "ts": m.ts.isoformat()} for m in self.recent_messages],
            "told_to_lead": self.told_to_lead,
        }


@dataclass(frozen=True)
class DeliveryReceipt:
    trace_id: str
    status: Literal["delivered", "queued"]  # delivered: o destino confirmou; queued: aceito para entrega assincrona
    delivered_at: datetime
    external_ref: str | None = None  # id no CRM/fila, se houver


class SinkUnavailable(Exception):
    """Falha transitoria do destino: o handoff fica pendente e a entrega e repetida depois."""


class SinkRejected(Exception):
    """Falha permanente: o destino recusou este pacote. Repetir nao adianta; alertar um humano."""


@runtime_checkable
class HandoffSink(Protocol):
    def deliver(self, package: HandoffPackage) -> DeliveryReceipt:
        """Entrega o pacote. Ver o contrato no docstring do modulo."""
        ...
"""Normalizacao dos slots antes de chamar a /quote. Higiene de ENTRADA, nao regra de negocio.

A API nao valida nada disto e responde 200 com preco errado (ver docs/FINDINGS.md 1.5): CEP ausente ou sem o zero a esquerda
nao aplica o agravo regional; `plano_id` vazio vira Essencial; `data_inicio` no passado e aceita. Por isso o agente normaliza e
valida ANTES de chamar. Na duvida, recusa o valor (o agente pergunta de novo) em vez de adivinhar.
"""
from __future__ import annotations

import re
from collections.abc import Iterable, Mapping
from dataclasses import dataclass
from datetime import date
from typing import Any


class SlotValueError(ValueError):
    """Valor de slot rejeitado. `code` e estavel e vai para logs e testes."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


@dataclass(frozen=True)
class SlotIssue:
    slot: str
    code: str


@dataclass(frozen=True)
class QuoteRequest:
    plano_id: str
    idade: int
    veiculo_ano: int
    cep: str | None = None            # 8 digitos; obrigatorio no fluxo de cotacao, opcional so na confirmacao da pre-checagem
    data_inicio: date | None = None   # hoje ou futura

    def to_payload(self) -> dict[str, Any]:
        payload: dict[str, Any] = {"plano_id": self.plano_id, "idade": self.idade, "veiculo_ano": self.veiculo_ano}
        if self.cep is not None:
            payload["cep"] = self.cep
        if self.data_inicio is not None:
            payload["data_inicio"] = self.data_inicio.isoformat()
        return payload


_DIGITS = re.compile(r"[0-9]+")
_ISO_DATE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")


def _as_int(value: object, code: str) -> int:
    if isinstance(value, bool):
        raise SlotValueError(code)
    if isinstance(value, int):
        return value
    if isinstance(value, str) and _DIGITS.fullmatch(value.strip()):
        return int(value.strip())
    raise SlotValueError(code)


def normalize_cep(value: object) -> str:
    """CEP como texto de 8 digitos. 7 digitos (zero a esquerda perdido) NAO e completado: pergunta de novo."""
    if value is None or isinstance(value, bool):
        raise SlotValueError("cep_ausente")
    if isinstance(value, int):
        raise SlotValueError("cep_nao_texto")  # um inteiro ja perdeu o zero a esquerda
    if not isinstance(value, str):
        raise SlotValueError("cep_invalido")
    digits = re.sub(r"[.\-\s]", "", value)
    if not _DIGITS.fullmatch(digits):
        raise SlotValueError("cep_invalido")
    if len(digits) == 8:
        return digits
    raise SlotValueError("cep_incompleto" if len(digits) == 7 else "cep_invalido")


def normalize_plano(value: object, known_plans: Iterable[str]) -> str:
    if not isinstance(value, str) or not value.strip():
        raise SlotValueError("plano_ausente")
    plano = value.strip().lower()
    if plano not in set(known_plans):
        raise SlotValueError("plano_desconhecido")
    return plano


def normalize_ano(value: object, today: date) -> int:
    ano = _as_int(value, "ano_invalido")
    if ano < 1950 or ano > 2100:
        raise SlotValueError("ano_invalido")
    if ano > today.year:
        raise SlotValueError("ano_modelo_futuro")  # a API recusa como "fora das faixas"; quem decide e o humano
    return ano


def normalize_idade(value: object) -> int:
    idade = _as_int(value, "idade_invalida")
    if not 0 <= idade <= 200:
        raise SlotValueError("idade_invalida")
    return idade  # elegibilidade (18 a 75) e da API, nao daqui


def normalize_data_inicio(value: object, today: date) -> date:
    if isinstance(value, date):
        d = value
    elif isinstance(value, str) and _ISO_DATE.fullmatch(value.strip()):
        try:
            d = date.fromisoformat(value.strip())
        except ValueError:
            raise SlotValueError("data_invalida") from None
    else:
        raise SlotValueError("data_invalida")
    if d < today:
        raise SlotValueError("data_no_passado")
    return d


def build_quote_request(raw: Mapping[str, object], *, today: date, known_plans: Iterable[str]) -> QuoteRequest | tuple[SlotIssue, ...]:
    """Pedido de cotacao completo ou, se faltar ou for invalido algum slot, TODAS as pendencias de uma vez."""
    known = tuple(known_plans)
    normalizers = (
        ("plano_id", lambda v: normalize_plano(v, known)),
        ("idade", normalize_idade),
        ("veiculo_ano", lambda v: normalize_ano(v, today)),
        ("cep", normalize_cep),
        ("data_inicio", lambda v: normalize_data_inicio(v, today)),
    )
    values: dict[str, Any] = {}
    issues: list[SlotIssue] = []
    for slot, fn in normalizers:
        if raw.get(slot) in (None, ""):
            issues.append(SlotIssue(slot, "ausente"))
            continue
        try:
            values[slot] = fn(raw[slot])
        except SlotValueError as exc:
            issues.append(SlotIssue(slot, exc.code))
    return tuple(issues) if issues else QuoteRequest(**values)
        return f"VerifiedSlots({self._data!r})"


@dataclass(frozen=True)
class NotQuotable:
    """Nao ha pedido de cotacao: o que falta (nunca dito), o que esta pendente (dito mas nao verificado) e o que a higiene de entrada recusou."""

    missing: tuple[str, ...]
    pending: tuple[SlotState, ...]
    issues: tuple[SlotIssue, ...] = ()


def plano_for(necessidade: str, planos: Mapping[str, Any]) -> str | None:
    """Necessidade -> plano pelo numero de coberturas (o menor plano que cobre o pedido). None se nao ha plano para a opcao."""
    tiers = sorted(planos["planos"], key=lambda p: len(p["coberturas"]))
    idx = NECESSIDADES.index(necessidade)
    return tiers[idx]["id"] if idx < len(tiers) else None


class SlotLedger:
    """O estado de verificacao dos slots de UMA conversa. O orquestrador alimenta com `ingest` (saida do LLM + texto do lead) e `answer`
    (resposta do lead a uma confirmacao), pergunta o que esta pendente com `question`, e so cota por `quote_request`."""

    def __init__(self) -> None:
        self._states: dict[str, SlotState] = {}
        self._attempts: dict[str, int] = {}

    def state(self, slot: str) -> SlotState | None:
        return self._states.get(slot)

    def attempts(self, slot: str) -> int:
        """Quantas vezes a confirmacao deste slot falhou (o orquestrador leva ao humano depois de 2: `DATA_AMBIGUOUS`)."""
        return self._attempts.get(slot, 0)

    def ingest(self, output: TurnOutput, lead_text: str, *, asked_slot: str | None = None) -> tuple[SlotState, ...]:
        """Confere cada slot que o modelo propos contra o texto do lead. Um valor novo SUBSTITUI o anterior do mesmo slot (correcao)."""
        reading = read_text(lead_text, asked_slot)
        out = []
        for slot in dict.fromkeys(s.slot for s in output.slots):
            st = anchor(slot, output.entries(slot), reading, asked_slot=asked_slot)
            self._states[slot] = st
            self._attempts.pop(slot, None)
            out.append(st)
        return tuple(out)

    def answer(self, slot: str, lead_text: str) -> SlotState | None:
        """Resolve uma confirmacao pendente com a resposta do lead, SEM LLM: "sim" confirma o valor proposto; um valor escrito pelo lead, unico
        e sem hesitacao, vale como dado dele. Qualquer outra coisa deixa pendente e conta uma tentativa."""
        st = self._states.get(slot)
        if st is None or st.quotable:
            return st
        reading = read_text(lead_text, slot)
        yes, no = bool(_YES_RX.match(reading.plain)), bool(_NO_RX.match(reading.plain))
        if yes and st.proposed is not None and not reading.hedge:
            new = SlotState(slot, Status.CONFIRMED, value=st.proposed, evidence=f"confirmou: {lead_text.strip()[:40]}")
        else:
            new = self._from_reply(slot, st, reading, denied=no)
        if not new.quotable:
            self._attempts[slot] = self._attempts.get(slot, 0) + 1
        self._states[slot] = new
        return new

    @staticmethod
    def _from_reply(slot: str, st: SlotState, reading: TextReading, *, denied: bool) -> SlotState:
        if slot == "necessidade":
            tier = None if reading.question else implied_tier(reading.plain)
            if tier is not None and not reading.hedge:
                return SlotState(slot, Status.CONFIRMED, value=tier[0], evidence=tier[1])
        else:
            cands = reading.candidates(slot)
            if len(cands) == 1 and not reading.hedge:
                return SlotState(slot, Status.CONFIRMED, value=cands[0].value, evidence=cands[0].text)
        return _pending(slot, Reason.DENIED if denied else (st.reason or Reason.OUT_OF_TEXT), candidates=st.candidates,
                        proposed=None if denied else st.proposed, note=st.note)

    def pending(self) -> tuple[SlotState, ...]:
        return tuple(st for st in self._states.values() if not st.quotable)

    def snapshot(self) -> dict[str, dict[str, Any]]:
        """O estado de cada slot, serializavel (JSON), para persistir. So o que o proprio lead escreveu (texto ja mascarado) e o que foi decidido sobre isso."""
        return {s: {"status": st.status.value, "value": st.value, "evidence": st.evidence, "reason": st.reason.value if st.reason else None,
                    "candidates": list(st.candidates), "proposed": st.proposed, "note": st.note} for s, st in self._states.items()}

    def question(self, slot: str, base: FactBase | None = None) -> str:
        """A pergunta de confirmacao (template) para um slot pendente, ou a pergunta do produto se ele ainda nao existe."""
        st = self._states.get(slot)
        if st is None or st.quotable:
            return questions.ask(slot, base)
        return questions.confirm(slot, proposed=st.proposed, candidates=st.candidates,
                                 derived_from=st.note if st.reason is Reason.DERIVED and st.note else None, base=base)

    def verified(self) -> VerifiedSlots:
        return VerifiedSlots(_MINT, {s: st.value for s, st in self._states.items() if st.quotable and st.value is not None})

    def quote_request(self, planos: Mapping[str, Any], *, today: date, plano_id: str | None = None) -> QuoteRequest | NotQuotable:
        """O UNICO caminho para um `QuoteRequest`. Cada campo vem de um slot verificado; `plano_id` sai da necessidade verificada, ou e o plano ALTERNATIVO
        que o orquestrador pede (objecao de preco: uma alternativa real via API), que precisa existir no /planos."""
        v = self.verified()
        pend = self.pending()
        pending_slots = {st.slot for st in pend}
        missing = tuple(s for s in SLOT_NAMES if s not in v and s not in pending_slots)
        if missing or pend:
            return NotQuotable(missing, pend)
        known = [p["id"] for p in planos["planos"]]
        plano = plano_id if plano_id is not None else plano_for(v["necessidade"], planos)
        if plano is not None and plano not in known:
            return NotQuotable((), (), (SlotIssue("plano_id", "plano_desconhecido"),))
        if plano is None:
            return NotQuotable((), (), (SlotIssue("necessidade", "sem_plano_correspondente"),))
        built = build_quote_request(
            {"plano_id": plano, "idade": v["idade"], "veiculo_ano": v["veiculo_ano"], "cep": v["cep"], "data_inicio": v["data_inicio"]},
            today=today, known_plans=[p["id"] for p in planos["planos"]])
        return NotQuotable((), (), built) if isinstance(built, tuple) else built


class QuoteGate:
    """O unico chamador do cliente da /quote. Se algum slot nao esta verificado, o cliente NAO e chamado."""

    def __init__(self, client: QuoteClient, planos: Mapping[str, Any]) -> None:
        self._client, self._planos = client, planos

    def quote(self, ledger: SlotLedger, *, today: date, plano_id: str | None = None, **client_kwargs: Any) -> QuoteOutcome | NotQuotable:
        built = ledger.quote_request(self._planos, today=today, plano_id=plano_id)
        if isinstance(built, NotQuotable):
            return built
        return self._client.quote(built, **client_kwargs)

