             "chamar": r"\bte chamar\b|\bchamo voce\b", "mesmo_chat": r"\bneste mesmo chat\b", "retorno": r"\bretorn",
             "ainda_hoje": r"\bainda hoje\b", "logo_mais": r"\blogo mais\b", "proximas": r"\bnas proximas\b"}
